const items = $input.all();

const config = $('02 - OSINT Config').first().json;

const lookbackDays = Number(config.lookback_days || 7);

const now = new Date();
const cutoffDate = new Date(
  now.getTime() - (lookbackDays * 24 * 60 * 60 * 1000)
);

// همه برندها: شرکت اصلی + رقبا
const brands = [
  {
    name: config.company.name,
    name_fa: config.company.name_fa,
    type: 'company',
    keywords: config.company.keywords || []
  },
  ...config.competitors.map(c => ({
    name: c.name,
    name_fa: c.name_fa,
    type: 'competitor',
    keywords: c.keywords || []
  }))
];

const results = [];

for (const item of items) {
  const data = item.json;

  const title = String(data.title || '').trim();

  const content = String(
    data.contentSnippet ||
    data.content ||
    data.description ||
    ''
  ).trim();

  const url = String(
    data.link ||
    data.url ||
    ''
  ).trim();

  const publishedRaw =
    data.isoDate ||
    data.pubDate ||
    data.published ||
    '';

  const publishedDate = new Date(publishedRaw);

  // 1. حذف رکورد ناقص
  if (!title || !url || !publishedRaw) {
    continue;
  }

  // 2. فقط بازه زمانی مشخص‌شده در Config
  if (
    isNaN(publishedDate.getTime()) ||
    publishedDate < cutoffDate ||
    publishedDate > now
  ) {
    continue;
  }

  // 3. متن قابل جست‌وجو
  const searchableText =
    `${title} ${content}`.toLowerCase();

  // 4. پیدا کردن تمام برندهای ذکرشده در خبر
  const matchedBrands = brands.filter(brand =>
    brand.keywords.some(keyword =>
      searchableText.includes(
        String(keyword).toLowerCase()
      )
    )
  );

  // اگر هیچ برند هدفی نبود، خبر حذف شود
  if (matchedBrands.length === 0) {
    continue;
  }

  results.push({
    json: {
      title,
      url,

      source: 'Mehr News',
      source_domain: 'mehrnews.com',

      published_date: publishedDate.toISOString(),

      matched_brands: matchedBrands.map(b => ({
        name: b.name,
        name_fa: b.name_fa,
        type: b.type
      })),

      primary_brand: matchedBrands[0].name,
      primary_brand_fa: matchedBrands[0].name_fa,

      content,

      collection_source: 'RSS',
      collection_channel: 'Mehr RSS'
    }
  });
}

return results;

const items = $input.all();

const config = $('02 - OSINT Config').first().json;

const output = [];

// نرمال‌سازی حروف فارسی برای Match مطمئن‌تر
function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/ي/g, 'ی')
    .replace(/ك/g, 'ک')
    .replace(/\u200c/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// لیست شرکت اصلی + رقبا
const brands = [
  {
    name: config.company.name,
    name_fa: config.company.name_fa,
    type: 'company',
    keywords: config.company.keywords || []
  },
  ...config.competitors.map(c => ({
    name: c.name,
    name_fa: c.name_fa,
    type: 'competitor',
    keywords: c.keywords || []
  }))
];

for (const item of items) {

  // Tavily خودش Query مربوط به این Search را در خروجی نگه می‌دارد
  const query = normalizeText(item.json.query);

  // مشخص کنیم این Search متعلق به کدام برند بوده
  const matchedBrand = brands.find(brand => {

    const possibleNames = [
      brand.name,
      brand.name_fa,
      ...brand.keywords
    ];

    return possibleNames.some(value => {
      const normalizedValue = normalizeText(value);

      return normalizedValue &&
        (
          query === normalizedValue ||
          query.includes(normalizedValue) ||
          normalizedValue.includes(query)
        );
    });
  });

  const results = Array.isArray(item.json.results)
    ? item.json.results
    : [];

  for (const result of results) {

    const title = String(result.title || '').trim();
    const url = String(result.url || '').trim();
    const content = String(result.content || '').trim();

    const publishedRaw =
      result.published_date ||
      result.publishedDate ||
      '';

    const publishedDate = new Date(publishedRaw);

    if (!title || !url) {
      continue;
    }

    output.push({
      json: {
        title,
        url,

        source: 'Digiato',
        source_domain: 'digiato.com',

        published_date:
          !isNaN(publishedDate.getTime())
            ? publishedDate.toISOString()
            : publishedRaw,

        matched_brands: matchedBrand
          ? [
              {
                name: matchedBrand.name,
                name_fa: matchedBrand.name_fa,
                type: matchedBrand.type
              }
            ]
          : [],

        primary_brand:
          matchedBrand?.name || 'Unknown',

        primary_brand_fa:
          matchedBrand?.name_fa || 'نامشخص',

        brand_type:
          matchedBrand?.type || 'unknown',

        search_query: item.json.query || '',

        content,

        tavily_score:
          result.score ?? null,

        collection_source: 'Tavily',

        collection_channel:
          'Tavily - Digiato'
      }
    });
  }
}

return output;

