const items = $input.all();

const config = $('02 - OSINT Config').first().json;

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/ي/g, 'ی')
    .replace(/ك/g, 'ک')
    .replace(/\u200c/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const brands = [
  {
    name: config.company.name,
    name_fa: config.company.name_fa,
    keywords: config.company.keywords || []
  },
  ...config.competitors.map(c => ({
    name: c.name,
    name_fa: c.name_fa,
    keywords: c.keywords || []
  }))
];

// کلماتی که ممکن است نشان دهند برند فقط به عنوان لینک خرید آمده
const shoppingTerms = [
  'خرید از',
  'خرید کنید',
  'لینک خرید',
  'برای خرید',
  'قیمت در',
  'قیمت محصول',
  'مشاهده قیمت',
  'فروشگاه',
  'خرید آنلاین',
  'سفارش دهید'
];

const output = [];

for (const item of items) {

  const data = item.json;

  const title = normalizeText(data.title);
  const content = normalizeText(data.content);

  const brand = brands.find(
    b => b.name === data.primary_brand
  );

  if (!brand) {
    continue;
  }

  const brandKeywords = [
    brand.name,
    brand.name_fa,
    ...brand.keywords
  ]
    .map(normalizeText)
    .filter(Boolean);

  // آیا برند در عنوان وجود دارد؟
  const titleHasBrand = brandKeywords.some(keyword =>
    title.includes(keyword)
  );

  // تعداد دفعات ذکر برند در متن
  let brandMentions = 0;

  for (const keyword of brandKeywords) {
    if (!keyword) continue;

    let position = 0;

    while (true) {
      const index = content.indexOf(keyword, position);

      if (index === -1) break;

      brandMentions++;
      position = index + keyword.length;
    }
  }

  // آیا برند در ابتدای متن مطرح شده؟
  const beginningOfContent = content.slice(0, 700);

  const brandInBeginning = brandKeywords.some(keyword =>
    beginningOfContent.includes(keyword)
  );

  // بررسی Context اطراف نام برند
  let shoppingContextHits = 0;

  for (const keyword of brandKeywords) {

    const index = content.indexOf(keyword);

    if (index === -1) continue;

    const start = Math.max(0, index - 100);
    const end = Math.min(
      content.length,
      index + keyword.length + 100
    );

    const context = content.slice(start, end);

    const hasShoppingContext = shoppingTerms.some(term =>
      context.includes(normalizeText(term))
    );

    if (hasShoppingContext) {
      shoppingContextHits++;
    }
  }

  // -------------------------
  // Relevance Score
  // -------------------------

  let relevanceScore = 0;

  // برند در عنوان = سیگنال بسیار قوی
  if (titleHasBrand) {
    relevanceScore += 4;
  }

  // برند در ابتدای مقاله
  if (brandInBeginning) {
    relevanceScore += 3;
  }

  // تعداد دفعات اشاره
  if (brandMentions >= 3) {
    relevanceScore += 3;
  } else if (brandMentions === 2) {
    relevanceScore += 2;
  } else if (brandMentions === 1) {
    relevanceScore += 1;
  }

  // اگر فقط Context خرید باشد، امتیاز کم شود
  if (
    shoppingContextHits > 0 &&
    !titleHasBrand &&
    brandMentions <= 1
  ) {
    relevanceScore -= 4;
  }

  // -------------------------
  // وضعیت
  // -------------------------

  let relevanceStatus;

  if (relevanceScore >= 4) {
    relevanceStatus = 'relevant';
  } else if (relevanceScore >= 2) {
    relevanceStatus = 'needs_ai_check';
  } else {
    relevanceStatus = 'irrelevant';
  }

  // موارد واضحاً نامرتبط را همین‌جا حذف می‌کنیم
  if (relevanceStatus === 'irrelevant') {
    continue;
  }

  output.push({
    json: {
      ...data,

      relevance_pre_score: relevanceScore,

      relevance_status: relevanceStatus,

      relevance_signals: {
        title_has_brand: titleHasBrand,
        brand_in_beginning: brandInBeginning,
        brand_mentions: brandMentions,
        shopping_context_hits: shoppingContextHits
      }
    }
  });
}

return output;

const items = $input.all();

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/ي/g, 'ی')
    .replace(/ك/g, 'ک')
    .replace(/\u200c/g, ' ')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeUrl(value) {
  try {
    const url = new URL(String(value || '').trim());

    // پارامترهای Tracking حذف شوند
    [
      'utm_source',
      'utm_medium',
      'utm_campaign',
      'utm_term',
      'utm_content',
      'fbclid',
      'gclid'
    ].forEach(param => url.searchParams.delete(param));

    // #fragment حذف شود
    url.hash = '';

    return url.toString()
      .replace(/\/$/, '')
      .toLowerCase();

  } catch {
    return String(value || '')
      .trim()
      .replace(/\/$/, '')
      .toLowerCase();
  }
}

// شباهت ساده بین دو عنوان
function titleSimilarity(a, b) {
  const wordsA = new Set(normalizeText(a).split(' ').filter(Boolean));
  const wordsB = new Set(normalizeText(b).split(' ').filter(Boolean));

  if (!wordsA.size || !wordsB.size) {
    return 0;
  }

  const intersection =
    [...wordsA].filter(word => wordsB.has(word)).length;

  const union =
    new Set([...wordsA, ...wordsB]).size;

  return union === 0 ? 0 : intersection / union;
}

const unique = [];

for (const item of items) {
  const data = item.json;

  const title = String(data.title || '').trim();
  const url = String(data.url || '').trim();

  if (!title || !url) {
    continue;
  }

  const normalizedUrl = normalizeUrl(url);

  // -------------------------
  // 1. Duplicate URL
  // -------------------------
  const sameUrl = unique.findIndex(existing =>
    existing._normalized_url === normalizedUrl
  );

  if (sameUrl !== -1) {
    continue;
  }

  // -------------------------
  // 2. عنوان بسیار مشابه
  // -------------------------
  let isSimilarDuplicate = false;

  for (const existing of unique) {
    const similarity = titleSimilarity(
      title,
      existing.title
    );

    // 80% شباهت یا بیشتر
    if (similarity >= 0.8) {
      isSimilarDuplicate = true;
      break;
    }
  }

  if (isSimilarDuplicate) {
    continue;
  }

  unique.push({
    ...data,
    _normalized_url: normalizedUrl
  });
}

// فیلد موقت داخلی را حذف کن
return unique.map(item => {
  const { _normalized_url, ...clean } = item;

  return {
    json: clean
  };
});

const items = $input.all();

const validItems = [];

for (const item of items) {
  const data = item.json;

  const title = String(data.title || '').trim();
  const url = String(data.url || '').trim();
  const source = String(data.source || '').trim();
  const publishedDate = String(data.published_date || '').trim();
  const primaryBrand = String(data.primary_brand || '').trim();

  // حداقل فیلدهای الزامی
  if (
    !title ||
    !url ||
    !source ||
    !publishedDate ||
    !primaryBrand ||
    primaryBrand === 'Unknown'
  ) {
    continue;
  }

  // تاریخ باید معتبر باشد
  const parsedDate = new Date(publishedDate);

  if (isNaN(parsedDate.getTime())) {
    continue;
  }

  validItems.push({
    ...data,
    published_date: parsedDate.toISOString()
  });
}

// جدیدترین خبرها اول
validItems.sort((a, b) => {
  return new Date(b.published_date) - new Date(a.published_date);
});

// Source ID نهایی
return validItems.map((data, index) => ({
  json: {
    source_id: `SRC-${String(index + 1).padStart(3, '0')}`,
    ...data
  }
}));

const items = $input.all();

const BATCH_SIZE = 10;

const articles = items.map(item => {
  const data = item.json;

  return {
    source_id: data.source_id,
    title: data.title,
    primary_brand: data.primary_brand,
    primary_brand_fa: data.primary_brand_fa,

    // برای کم کردن Token، فقط بخش کافی از متن را می‌فرستیم
    content: String(data.content || '').slice(0, 1800),

    source: data.source,
    published_date: data.published_date
  };
});

const output = [];

for (let i = 0; i < articles.length; i += BATCH_SIZE) {

  const batch = articles.slice(i, i + BATCH_SIZE);

  output.push({
    json: {
      batch_id: `RB-${String(
        Math.floor(i / BATCH_SIZE) + 1
      ).padStart(2, '0')}`,

      article_count: batch.length,

      articles: batch
    }
  });
}

return output;

const aiItems = $input.all();

// خبرهای اصلی دارای Source ID
const originalItems =
  $('17 - Validate & Assign Source IDs').all();

const articleMap = new Map();

for (const item of originalItems) {
  const sourceId = String(item.json.source_id || '').trim();

  if (sourceId) {
    articleMap.set(sourceId, item.json);
  }
}

const decisions = new Map();

for (const item of aiItems) {

  let text = String(item.json.text || '').trim();

  // اگر مدل ```json گذاشته باشد حذفش کن
  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let parsed;

  try {
    parsed = JSON.parse(text);
  } catch (error) {
    throw new Error(
      `AI returned invalid JSON: ${error.message}`
    );
  }

  if (!Array.isArray(parsed.results)) {
    throw new Error(
      'AI output does not contain a results array.'
    );
  }

  for (const result of parsed.results) {

    const sourceId =
      String(result.source_id || '').trim();

    // مدل حق اختراع Source ID ندارد
    if (!articleMap.has(sourceId)) {
      throw new Error(
        `Invalid or invented Source ID: ${sourceId}`
      );
    }

    // یک خبر نباید دو تصمیم داشته باشد
    if (decisions.has(sourceId)) {
      throw new Error(
        `Duplicate AI decision for ${sourceId}`
      );
    }

    const score =
      Number(result.relevance_score);

    if (
      !Number.isFinite(score) ||
      score < 0 ||
      score > 100
    ) {
      throw new Error(
        `Invalid relevance score for ${sourceId}`
      );
    }

    if (
      typeof result.is_relevant !== 'boolean'
    ) {
      throw new Error(
        `Invalid is_relevant value for ${sourceId}`
      );
    }

    decisions.set(sourceId, {
      is_relevant: result.is_relevant,
      relevance_score: Math.round(score),
      relevance_reason:
        String(result.relevance_reason || '').trim()
    });
  }
}

// AI باید برای تک تک خبرها پاسخ داده باشد
for (const sourceId of articleMap.keys()) {

  if (!decisions.has(sourceId)) {
    throw new Error(
      `Missing AI decision for ${sourceId}`
    );
  }
}

const output = [];

for (const [sourceId, article] of articleMap) {

  const decision = decisions.get(sourceId);

  let finalStatus;

  // تصمیم قطعی مرتبط
  if (
    decision.is_relevant === true &&
    decision.relevance_score >= 70
  ) {
    finalStatus = 'relevant';

  // تصمیم قطعی نامرتبط
  } else if (
    decision.is_relevant === false &&
    decision.relevance_score < 50
  ) {
    finalStatus = 'irrelevant';

  // موارد مرزی یا متناقض
  } else {
    finalStatus = 'needs_review';
  }

  output.push({
    json: {
      ...article,

      ai_relevance:
        decision.is_relevant,

      ai_relevance_score:
        decision.relevance_score,

      ai_relevance_reason:
        decision.relevance_reason,

      final_relevance_status:
        finalStatus
    }
  });
}

return output;

const items = $input.all();

const BATCH_SIZE = 10;

const articles = items.map(item => {
  const data = item.json;

  return {
    source_id: data.source_id,

    title: data.title,

    primary_brand: data.primary_brand,
    primary_brand_fa: data.primary_brand_fa,
    brand_type: data.brand_type || '',

    source: data.source,
    published_date: data.published_date,

    // متن کافی برای تحلیل، بدون مصرف Token غیرضروری
    content: String(data.content || '').slice(0, 2500),

    // نتیجه مرحله قبلی هم برای Context نگه می‌داریم
    relevance_score: data.ai_relevance_score
  };
});

const output = [];

for (let i = 0; i < articles.length; i += BATCH_SIZE) {

  const batch = articles.slice(i, i + BATCH_SIZE);

  output.push({
    json: {
      batch_id: `AB-${String(
        Math.floor(i / BATCH_SIZE) + 1
      ).padStart(2, '0')}`,

      article_count: batch.length,

      articles: batch
    }
  });
}

return output;

