// ==================================================
// Helper: Impact Factor Validation
// ==================================================

function validateImpactFactor(
  value,
  field,
  sourceId
) {

  const number = Number(value);

  if (
    !Number.isInteger(number) ||
    number < 0 ||
    number > 2
  ) {
    throw new Error(
      `Invalid ${field} for ${sourceId}: ${value}`
    );
  }

  return number;
}

// ==================================================
// Parse AI Output
// ==================================================

for (const item of aiItems) {

  let text = String(
    item.json.text || ''
  ).trim();

  // حذف ```json و ``` در صورت وجود
  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let parsed;

  try {

    parsed = JSON.parse(text);

  } catch (error) {

    throw new Error(
      `Business Analysis returned invalid JSON: ${error.message}`
    );
  }

  if (!Array.isArray(parsed.results)) {

    throw new Error(
      'Business Analysis output does not contain a results array.'
    );
  }

  // ==================================================
  // Validate Each Article Analysis
  // ==================================================

  for (const result of parsed.results) {

    const sourceId =
      String(
        result.source_id || ''
      ).trim();

    // -----------------------------
    // Source ID Guardrail
    // -----------------------------

    if (!articleMap.has(sourceId)) {

      throw new Error(
        `Invalid or invented Source ID: ${sourceId}`
      );
    }

    if (analyses.has(sourceId)) {

      throw new Error(
        `Duplicate analysis for ${sourceId}`
      );
    }

    // ==================================================
    // Category
    // ==================================================

    const rawCategory =
      String(
        result.category || ''
      ).trim();

    const category =
      categoryAliases[rawCategory] ||
      rawCategory;

    if (!allowedCategories.has(category)) {

      throw new Error(
        `Invalid category for ${sourceId}: ${rawCategory}`
      );
    }

    // ==================================================
    // Sentiment
    // ==================================================

    const sentiment =
      String(
        result.sentiment || ''
      ).trim();

    if (!allowedSentiments.has(sentiment)) {

      throw new Error(
        `Invalid sentiment for ${sourceId}: ${sentiment}`
      );
    }

    // ==================================================
    // Secondary Tags
    // ==================================================

    const secondaryTags =
      Array.isArray(result.secondary_tags)
        ? result.secondary_tags
            .map(tag =>
              String(tag || '').trim()
            )
            .filter(Boolean)
            .slice(0, 3)
        : [];

    // ==================================================
    // Summary & Claim
    // ==================================================

    const shortSummary =
      String(
        result.short_summary || ''
      ).trim();

    const keyClaim =
      String(
        result.key_claim || ''
      ).trim();

    if (!shortSummary) {

      throw new Error(
        `Missing short_summary for ${sourceId}`
      );
    }

    if (!keyClaim) {

      throw new Error(
        `Missing key_claim for ${sourceId}`
      );
    }

    // ==================================================
    // Risk
    // ==================================================

    const riskExists =
      result.risk?.exists === true;

    let riskType =
      String(
        result.risk?.type || 'none'
      ).trim();

    let riskDescription =
      String(
        result.risk?.description || ''
      ).trim();

    if (!allowedRiskTypes.has(riskType)) {

      throw new Error(
        `Invalid risk type for ${sourceId}: ${riskType}`
      );
    }

    // ==================================================
    // Risk Impact Factors
    // ==================================================

    let businessScope =
      validateImpactFactor(
        result.risk_impact_factors
          ?.business_scope ?? 0,
        'business_scope',
        sourceId
      );

    let financialEffect =
      validateImpactFactor(
        result.risk_impact_factors
          ?.financial_effect ?? 0,
        'financial_effect',
        sourceId
      );

    let reputationEffect =
      validateImpactFactor(
        result.risk_impact_factors
          ?.reputation_effect ?? 0,
        'reputation_effect',
        sourceId
      );

    let urgency =
      validateImpactFactor(
        result.risk_impact_factors
          ?.urgency ?? 0,
        'urgency',
        sourceId
      );

    // اگر Risk وجود ندارد،
    // Impact باید به صورت قطعی صفر شود.
    if (!riskExists) {

      riskType = 'none';
      riskDescription = '';

      businessScope = 0;
      financialEffect = 0;
      reputationEffect = 0;
      urgency = 0;
    }

    // ==================================================
    // Rule-Based Impact Calculation
    // ==================================================

    const impactScore =
      businessScope +
      financialEffect +
      reputationEffect +
      urgency;

    let impactLevel = 'None';

    if (riskExists) {

      if (impactScore <= 2) {

        impactLevel = 'Low';

      } else if (impactScore <= 5) {

        impactLevel = 'Medium';

      } else {

        impactLevel = 'High';
      }
    }

    // ==================================================
    // Opportunity
    // ==================================================

    const opportunityExists =
      result.opportunity?.exists === true;

    const rawOpportunityType =
      String(
        result.opportunity?.type || 'none'
      ).trim();

    let opportunityType =
      opportunityTypeAliases[
        rawOpportunityType
      ] ||
      rawOpportunityType;

    let opportunityDescription =
      String(
        result.opportunity?.description || ''
      ).trim();

    if (
      !allowedOpportunityTypes.has(
        opportunityType
      )
    ) {

      throw new Error(
        `Invalid opportunity type for ${sourceId}: ${rawOpportunityType}`
      );
    }

    // اگر Opportunity وجود ندارد،
    // Type و Description را استاندارد می‌کنیم.
    if (!opportunityExists) {

      opportunityType = 'none';
      opportunityDescription = '';
    }

    // ==================================================
    // Management Signal
    // ==================================================

    const managementSignal =
      String(
        result.management_signal || ''
      ).trim();

    if (
      !allowedManagementSignals.has(
        managementSignal
      )
    ) {

      throw new Error(
        `Invalid management signal for ${sourceId}: ${managementSignal}`
      );
    }

    // ==================================================
    // Store Validated Analysis
    // ==================================================

    analyses.set(
      sourceId,
      {

        // Category
        category,

        // برای Debug نگه می‌داریم
        category_raw:
          rawCategory,

        secondary_tags:
          secondaryTags,

        sentiment,

        // Summary
        short_summary:
          shortSummary,

        key_claim:
          keyClaim,

        // Risk
        risk_exists:
          riskExists,

        risk_type:
          riskType,

        risk_description:
          riskDescription,

        // Impact Factors
        impact_business_scope:
          businessScope,

        impact_financial_effect:
          financialEffect,

        impact_reputation_effect:
          reputationEffect,

        impact_urgency:
          urgency,

        // Final Impact
        impact_score:
          impactScore,

        impact_level:
          impactLevel,

        // Opportunity
        opportunity_exists:
          opportunityExists,

        opportunity_type:
          opportunityType,

        // برای Debug
        opportunity_type_raw:
          rawOpportunityType,

        opportunity_description:
          opportunityDescription,

        // Management
        management_signal:
          managementSignal
      }
    );
  }
}

