  } else {

    sourceTier = 'other_public_source';
    sourceQualityScore = 1;
  }

  // --------------------------------
  // 2. Evidence status
  // --------------------------------

  // فعلاً هر رکورد یک Source مستقل دارد.
  // بعد از Tavily Verification ممکن است بیشتر شود.
  const independentSources = 1;

  const officialConfirmation =
    sourceTier === 'official';

  // --------------------------------
  // 3. Initial Confidence
  // --------------------------------

  let confidenceScore = 0;

  // کیفیت منبع
  confidenceScore += sourceQualityScore * 2;

  // تأیید رسمی امتیاز بسیار بالایی دارد
  if (officialConfirmation) {
    confidenceScore += 4;
  }

  /*
    امتیاز فعلی معمولاً:

    Specialist/Major news:
    2 × 2 = 4

    Official:
    3 × 2 + 4 = 10
  */

  let confidenceLevel;

  if (confidenceScore >= 8) {
    confidenceLevel = 'High';

  } else if (confidenceScore >= 4) {
    confidenceLevel = 'Medium';

  } else {
    confidenceLevel = 'Low';
  }

  // --------------------------------
  // 4. آیا Verification لازم است؟
  // --------------------------------

  let verificationRequired = false;

  const verificationReasons = [];

  // Risk متوسط یا بالا را با یک منبع تنها رها نمی‌کنیم
  if (
    data.risk_exists === true &&
    Number(data.impact_score || 0) >= 3 &&
    independentSources < 2
  ) {
    verificationRequired = true;

    verificationReasons.push(
      'meaningful_risk_single_source'
