  ) {
    verificationRequired = true;

    verificationReasons.push(
      'management_action_single_source'
    );
  }

  // منبع ضعیف
  if (confidenceLevel === 'Low') {
    verificationRequired = true;

    verificationReasons.push(
      'low_source_confidence'
    );
  }

  output.push({
    json: {
      ...data,

      source_tier: sourceTier,
      source_quality_score: sourceQualityScore,

      independent_sources: independentSources,
      official_confirmation: officialConfirmation,

      confidence_score_initial: confidenceScore,
      confidence_level_initial: confidenceLevel,

      verification_required: verificationRequired,
      verification_reasons: verificationReasons
    }
  });
}

