]);

// استخراج Domain از URL
// این نسخه برای URLهای فارسی/Encode شده هم مقاوم‌تر است.
function getDomain(url) {
  const value = String(url || '').trim();

  const match = value.match(
    /^https?:\/\/([^\/?#]+)/i
  );

  if (!match) {
    return '';
  }

  return match[1]
    .toLowerCase()
    .replace(/^www\./, '')
    .trim();
}

const output = [];

for (let i = 0; i < searchItems.length; i++) {

  const response = searchItems[i].json;

  // ورودی متناظر از Node 27
  const verificationInput =
    verificationInputs[i]?.json ||
    verificationInputs[0]?.json ||
    {};

  // پشتیبانی از چند ساختار احتمالی HTTP Request
  let results = [];

  if (Array.isArray(response.results)) {

    results = response.results;

  } else if (
    response.body &&
    Array.isArray(response.body.results)
  ) {

    results = response.body.results;

  } else if (
    response.data &&
    Array.isArray(response.data.results)
  ) {

    results = response.data.results;
  }

  // Domain منبع اصلی خبر
  const originalDomain = String(
    verificationInput.original_source_domain || ''
  )
    .toLowerCase()
    .replace(/^www\./, '')
    .trim();

  const acceptedResults = [];
  const rejectedResults = [];
  const allResultDomains = [];

  // یک Domain فقط یک Independent Source محسوب شود
  const seenDomains = new Set();

  for (const result of results) {

    const url = String(result.url || '').trim();

    const domain = getDomain(url);

    allResultDomains.push(
      domain || 'invalid-url'
    );

    // -------------------------
    // URL نامعتبر
    // -------------------------
    if (!domain) {

      rejectedResults.push({
        title: String(result.title || '').trim(),
        url,
        domain: '',
        reason: 'invalid_url'
      });

      continue;
    }

    // -------------------------
    // Domain خارج از Allowlist
    // -------------------------
    if (!allowedDomains.has(domain)) {

      rejectedResults.push({
        title: String(result.title || '').trim(),
        url,
        domain,
        reason: 'domain_not_allowed'
      });

      continue;
    }

    // -------------------------
    // همان Source اصلی خبر
    // مستقل محسوب نمی‌شود
    // -------------------------
    if (domain === originalDomain) {

      rejectedResults.push({
        title: String(result.title || '').trim(),
        url,
        domain,
        reason: 'same_as_original_source'
      });

      continue;
    }

    // -------------------------
    // چند نتیجه از یک Domain
    // فقط یک Independent Source
    // -------------------------
    if (seenDomains.has(domain)) {

      rejectedResults.push({
        title: String(result.title || '').trim(),
        url,
        domain,
        reason: 'duplicate_domain'
      });

      continue;
    }

    seenDomains.add(domain);

    // -------------------------
    // Candidate معتبر
    // -------------------------
    acceptedResults.push({

      title:
        String(result.title || '').trim(),

      url,

      domain,

      content:
        String(result.content || '').trim(),

      score:
        result.score ?? null,

      published_date:
        result.published_date || ''
    });
  }

  output.push({
    json: {

      // Claim اصلی
      source_id:
        verificationInput.verification_source_id ||
        verificationInput.source_id ||
        '',

      key_claim:
        verificationInput.key_claim || '',

      original_source_domain:
        originalDomain,

      verification_query:
        verificationInput.verification_query || '',

      // -------------------------
      // خروجی اصلی
      // -------------------------

      candidate_count:
        acceptedResults.length,

      candidate_domains:
        [...seenDomains],

      verification_candidates:
        acceptedResults,

      // -------------------------
      // Debug
      // بعداً می‌توانیم حذفشان کنیم
      // -------------------------

      debug_result_count:
        results.length,

      debug_result_domains:
        allResultDomains,

      rejected_results:
        rejectedResults
    }
  });
}

return output;

