      throw new Error(
        `Invalid evidence relation for ${url}: ${relation}`
      );
    }

    const evidenceScore =
      Number(result.evidence_score);

    if (
      !Number.isFinite(evidenceScore) ||
      evidenceScore < 0 ||
      evidenceScore > 100
    ) {
      throw new Error(
        `Invalid evidence score for ${url}`
      );
    }

    const evidence = {
      url,
      domain,
      relation,
      evidence_score:
        Math.round(evidenceScore),

      reason:
        String(result.reason || '').trim()
    };

    validatedEvidence.push(evidence);

    // فقط Evidence نسبتاً قوی را حساب می‌کنیم
    if (
      relation === 'supports' &&
      evidenceScore >= 70
    ) {
      supportingDomains.add(domain);
    }

    if (
      relation === 'contradicts' &&
      evidenceScore >= 70
    ) {
      contradictingDomains.add(domain);
    }
  }

  const supportingSourceCount =
    supportingDomains.size;

  const contradictingSourceCount =
    contradictingDomains.size;

  // Source اصلی همیشه یک منبع است
  const independentSources =
    1 + supportingSourceCount;

  let verificationStatus;
  let finalConfidenceScore =
    Number(
      originalArticle.confidence_score_initial || 0
    );

  let finalConfidenceLevel =
    originalArticle.confidence_level_initial ||
    'Low';

  let needsHumanReview = false;

  // --------------------------------
  // Evidence متناقض
  // --------------------------------
  if (contradictingSourceCount > 0) {

    verificationStatus =
      'conflicting_evidence';

    needsHumanReview = true;

    // تعارض را High Confidence نمی‌کنیم
    finalConfidenceScore =
      Math.min(finalConfidenceScore, 3);

    finalConfidenceLevel = 'Low';

  // --------------------------------
  // تأیید مستقل پیدا شده
  // --------------------------------
  } else if (supportingSourceCount > 0) {

    verificationStatus =
      'independently_supported';

    /*
      یک منبع مستقل معتبر یعنی:
      Source اصلی + حداقل یک Source مستقل

      برای همین +4 می‌دهیم تا
      یک خبر Medium معمولی با تأیید مستقل
      بتواند به High برسد.
    */
    finalConfidenceScore = Math.min(
      10,
      finalConfidenceScore +
      (supportingSourceCount * 4)
    );

    if (finalConfidenceScore >= 8) {
      finalConfidenceLevel = 'High';

    } else if (finalConfidenceScore >= 4) {
      finalConfidenceLevel = 'Medium';

    } else {
      finalConfidenceLevel = 'Low';
    }

  // --------------------------------
  // Candidate بود ولی Claim را تأیید نکرد
  // --------------------------------
  } else {

    verificationStatus =
      'candidate_found_but_not_verified';

    // Confidence اولیه حفظ می‌شود
  }

  output.push({
    json: {
      ...originalArticle,

      verification_attempted: true,

      verification_status:
        verificationStatus,

      supporting_independent_sources:
        supportingSourceCount,

      contradicting_sources:
        contradictingSourceCount,

      independent_sources:
        independentSources,

      verification_sources:
        validatedEvidence,

      final_confidence_score:
        finalConfidenceScore,

      final_confidence_level:
        finalConfidenceLevel,

      needs_human_review:
        needsHumanReview
    }
  });
}

return output;

