function validateSourceIds(sourceIds, sectionName) {

  if (!Array.isArray(sourceIds)) {
    throw new Error(
      `source_ids must be an array in ${sectionName}`
    );
  }

  for (const sourceId of sourceIds) {

    const id = String(sourceId || '').trim();

    if (!allowedSources.has(id)) {
      throw new Error(
        `Invalid or invented citation "${id}" in ${sectionName}`
      );
    }
  }
}

for (const item of aiItems) {

  let text = String(item.json.text || '').trim();

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let report;

  try {
    report = JSON.parse(text);
  } catch (error) {
    throw new Error(
      `Executive Analysis returned invalid JSON: ${error.message}`
    );
  }

  // --------------------------------
  // Executive Summary
  // --------------------------------

  if (!Array.isArray(report.executive_summary)) {
    throw new Error(
      'executive_summary must be an array'
    );
  }

  for (const finding of report.executive_summary) {

    validateSourceIds(
      finding.source_ids,
      'executive_summary'
    );
  }

  // --------------------------------
  // Company Media Topics
  // --------------------------------

  if (!Array.isArray(report.company_media_topics)) {
    throw new Error(
      'company_media_topics must be an array'
    );
  }

  for (const topic of report.company_media_topics) {

    validateSourceIds(
      topic.source_ids,
      'company_media_topics'
    );
  }

  // --------------------------------
  // Competitor Focus
  // --------------------------------

  if (!Array.isArray(report.competitor_focus)) {
    throw new Error(
      'competitor_focus must be an array'
    );
  }

  for (const competitor of report.competitor_focus) {

    validateSourceIds(
      competitor.source_ids,
      'competitor_focus'
    );

    const allowedEvidenceLevels = [
      'sufficient',
      'limited',
      'insufficient'
    ];

    if (
      !allowedEvidenceLevels.includes(
        competitor.evidence_level
      )
    ) {
      throw new Error(
        `Invalid competitor evidence_level: ${competitor.evidence_level}`
      );
    }
  }

  // --------------------------------
  // Risks
  // --------------------------------

  if (!Array.isArray(report.top_risks)) {
    throw new Error(
      'top_risks must be an array'
    );
  }

  for (const risk of report.top_risks) {

    validateSourceIds(
      risk.source_ids,
      'top_risks'
    );

    /*
      Risk Impact را مدل حق ندارد تغییر دهد.
      حداقل یکی از Citationها باید
      همان Risk را در دیتاست داشته باشد.
    */

    let matchingRiskFound = false;

    for (const sourceId of risk.source_ids) {

      const evidence =
        allowedSources.get(sourceId);

      if (!evidence) continue;

      if (evidence.risk_exists !== true) {
        continue;
      }

      if (
        String(evidence.impact_level) ===
          String(risk.impact_level) &&
        Number(evidence.impact_score) ===
          Number(risk.impact_score)
      ) {
        matchingRiskFound = true;
        break;
      }
    }

    if (!matchingRiskFound) {
      throw new Error(
        `Risk impact does not match source evidence for "${risk.title}"`
      );
    }
  }

  // --------------------------------
  // Opportunities
  // --------------------------------

  if (!Array.isArray(report.opportunities)) {
    throw new Error(
      'opportunities must be an array'
    );
  }

  for (const opportunity of report.opportunities) {

    validateSourceIds(
      opportunity.source_ids,
      'opportunities'
    );

    // حداقل یکی از Sourceها باید Opportunity داشته باشد
    const supported =
      opportunity.source_ids.some(sourceId => {

        const evidence =
          allowedSources.get(sourceId);

        return evidence?.opportunity_exists === true;
      });

    if (!supported) {
      throw new Error(
        `Opportunity has no supporting evidence: "${opportunity.title}"`
      );
    }
  }

  // --------------------------------
  // Recommended Actions
  // --------------------------------

  if (!Array.isArray(report.recommended_actions)) {
    throw new Error(
      'recommended_actions must be an array'
    );
  }

  const allowedPriorities = [
    'High',
    'Medium',
    'Low'
  ];

  for (const action of report.recommended_actions) {

    validateSourceIds(
      action.source_ids,
      'recommended_actions'
    );

    if (
      !allowedPriorities.includes(
        action.priority
      )
    ) {
      throw new Error(
        `Invalid action priority: ${action.priority}`
      );
    }
  }

  // --------------------------------
  // Limitations
  // --------------------------------

  if (!Array.isArray(report.limitations)) {
    throw new Error(
      'limitations must be an array'
    );
  }

  output.push({
    json: {
      validation_status: 'valid',

      allowed_source_ids:
        [...allowedSources.keys()],

      executive_report:
        report
    }
  });
}

return output;

