function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function safeUrl(value) {
  const url = String(value || '').trim();

  if (
    url.startsWith('http://') ||
    url.startsWith('https://')
  ) {
    return esc(url);
  }

  return '#';
}

function formatDate(value) {
  if (!value) return '-';

  try {
    const date = new Date(value);

    if (isNaN(date.getTime())) {
      return esc(value);
    }

    return new Intl.DateTimeFormat('fa-IR', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    }).format(date);

  } catch {
    return esc(value);
  }
}

function citationLinks(ids = []) {

  if (!Array.isArray(ids) || ids.length === 0) {
    return `
      <span class="citation muted">
        بدون منبع
      </span>
    `;
  }

  return ids.map(id => {

    const source = sourceIndex[id];

    if (!source) {
      return `
        <span class="citation invalid">
          ${esc(id)}
        </span>
      `;
    }

    return `
      <a
        class="citation"
        href="${safeUrl(source.url)}"
        target="_blank"
        rel="noopener noreferrer"
        title="${esc(source.title)}"
      >
        ${esc(id)}
      </a>
    `;
  }).join('');
}

function confidenceClass(value) {
  const v = String(value || '').toLowerCase();

  if (v === 'high') return 'high';
  if (v === 'medium') return 'medium';

  return 'low';
}

function impactClass(value) {
  const v = String(value || '').toLowerCase();

  if (v === 'high') return 'high';
  if (v === 'medium') return 'medium';
  if (v === 'low') return 'low';

  return 'neutral';
}

